#!/bin/bash
#SBATCH --job-name=loki-vae
#SBATCH --partition=work1
#SBATCH --gres=gpu:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=64G
#SBATCH --time=1-00:00:00
#SBATCH --output=log/slurm/loki-vae-%j.out
#SBATCH --error=log/slurm/loki-vae-%j.err

# === LOKI VAE Training on 500K Dataset ===
# Trains the morphology VAE using WebDataset format on a single GPU.
# Model is small (~1.1 MB), so one GPU is sufficient.
#
# Prerequisites:
#   - 500K webdataset.tar must exist (generated by gen_data_cluster.sh)
#   - Either at /scratch/yinhonq/loki_data/webdataset_500k.tar or locally as webdataset.tar
#
# Submit:
#   sbatch --gres=gpu:a100:1 scripts/train_vae_cluster.sh
#   sbatch --gres=gpu:h200:1 scripts/train_vae_cluster.sh

# Setup environment
module load cuda/12.3
source activate loki

# Navigate to repo
cd /home/yinhonq/test_pipelines/loki-multitask-eval-llm

# Create log directories
mkdir -p log/slurm log/train_vae

# Print job info
echo "=== LOKI VAE Training Job ==="
echo "Job ID: $SLURM_JOB_ID"
echo "Node: $SLURM_NODELIST"
echo "GPUs (CUDA_VISIBLE_DEVICES): $CUDA_VISIBLE_DEVICES"
echo "Start time: $(date)"
echo ""

echo "--- GPU Details ---"
nvidia-smi --query-gpu=index,name,memory.total,memory.free,driver_version --format=csv,noheader
echo ""
nvidia-smi
echo ""

echo "--- System RAM ---"
free -h
echo ""

# Symlink webdataset from scratch if not already present locally
if [ ! -f webdataset.tar ]; then
    echo "Symlinking webdataset from scratch..."
    ln -sf /scratch/yinhonq/loki_data/webdataset_500k.tar webdataset.tar
fi
echo "webdataset.tar size: $(du -h webdataset.tar | cut -f1)"
echo ""

# Hyperparameters (same as paper for 500K dataset)
BATCH_SIZE=4096
H_DIM=32
D_DEPTH=32
LR=1e-4
WD=1e-5
NUM_LAYER=4
NUM_HEAD=4
FACTOR=8
NUM_EPOCHS=200

LOG_FILE="log/train_vae/VAE_500k_hdim${H_DIM}_depth${D_DEPTH}_LR_${LR}_WD_${WD}_L${NUM_LAYER}_H${NUM_HEAD}_F${FACTOR}_beta0.01_bsize${BATCH_SIZE}_epochs${NUM_EPOCHS}.log"

# --- Background resource monitor ---
MONITOR_LOG="log/slurm/loki-vae-${SLURM_JOB_ID}-monitor.log"
MONITOR_INTERVAL=120  # seconds between snapshots

TOTAL_EPOCHS=$NUM_EPOCHS

format_duration() {
    local secs=$1
    printf "%dh %dm %ds" $(( secs / 3600 )) $(( (secs % 3600) / 60 )) $(( secs % 60 ))
}

monitor_resources() {
    echo "=== VAE Training Resource Monitor (interval: ${MONITOR_INTERVAL}s) ===" > "$MONITOR_LOG"
    local monitor_start=$(date +%s)
    while true; do
        {
            local now=$(date +%s)
            local elapsed=$(( now - monitor_start ))
            echo "--- $(date '+%Y-%m-%d %H:%M:%S') [elapsed: $(format_duration $elapsed)] ---"

            # GPU utilization and memory
            echo "[GPU]"
            nvidia-smi --query-gpu=index,utilization.gpu,utilization.memory,memory.used,memory.total,temperature.gpu,power.draw --format=csv,noheader 2>/dev/null
            echo ""

            # System RAM
            echo "[RAM] $(free -h | grep Mem)"
            echo ""

            # Training progress and ETA
            # Parse current epoch from log: looks for "Epoch {n}/{total}" pattern
            local current_epoch=$(grep -oP 'Epoch \K[0-9]+(?=/)' "$LOG_FILE" 2>/dev/null | tail -1)
            if [ -n "$current_epoch" ] && [ "$current_epoch" -gt 0 ] && [ "$elapsed" -gt 0 ]; then
                local remaining_epochs=$(( TOTAL_EPOCHS - current_epoch ))
                local secs_per_epoch=$(echo "$elapsed $current_epoch" | awk '{printf "%d", $1 / $2}')
                local eta_secs=$(( remaining_epochs * secs_per_epoch ))
                local pct=$(echo "$current_epoch $TOTAL_EPOCHS" | awk '{printf "%.1f", $1/$2*100}')

                echo "[ETA] Epoch: $current_epoch / $TOTAL_EPOCHS ($pct%)"
                echo "[ETA] Avg time per epoch: $(format_duration $secs_per_epoch)"
                echo "[ETA] Estimated time remaining: $(format_duration $eta_secs)"
                echo "[ETA] Estimated completion: $(date -d "+${eta_secs} seconds" '+%Y-%m-%d %H:%M:%S' 2>/dev/null || echo 'N/A')"

                # Progress bar (50 chars wide)
                local filled=$(( current_epoch * 50 / TOTAL_EPOCHS ))
                local empty=$(( 50 - filled ))
                printf "[ETA] [" >> "$MONITOR_LOG"
                printf '%0.s#' $(seq 1 $filled 2>/dev/null) >> "$MONITOR_LOG"
                printf '%0.s-' $(seq 1 $empty 2>/dev/null) >> "$MONITOR_LOG"
                printf '] %s%%\n' "$pct" >> "$MONITOR_LOG"
            else
                echo "[ETA] Waiting for training to start..."
            fi
            echo ""

            # Training progress (last few lines of log)
            echo "[TRAIN] Last log entries:"
            tail -3 "$LOG_FILE" 2>/dev/null || echo "  (no log yet)"
            echo ""

            # Checkpoint status
            echo "[CKPT] Latest checkpoints:"
            ls -lht vae/checkpoints/ 2>/dev/null | head -4 || echo "  (none yet)"
            echo ""
        } >> "$MONITOR_LOG"
        sleep "$MONITOR_INTERVAL"
    done
}

monitor_resources &
MONITOR_PID=$!
echo "Resource monitor started (PID: $MONITOR_PID, log: $MONITOR_LOG)"
echo ""

# Cleanup monitor on exit
cleanup_monitor() {
    if kill -0 "$MONITOR_PID" 2>/dev/null; then
        kill "$MONITOR_PID" 2>/dev/null
        echo "Resource monitor stopped."
    fi
}
trap cleanup_monitor EXIT

TRAIN_START=$(date +%s)
echo "Training VAE with 500K dataset..."
echo "Log file: $LOG_FILE"
echo "Monitor log: $MONITOR_LOG"
echo ""

PYTHONPATH=. python vae/train.py \
    --gpu 0 \
    --lr $LR \
    --batch_size $BATCH_SIZE \
    --min_beta 1e-5 \
    --max_beta 1e-2 \
    --epochs $NUM_EPOCHS \
    --factor $FACTOR \
    --n_head $NUM_HEAD \
    --n_layer $NUM_LAYER \
    --d_depth $D_DEPTH \
    --h_dim $H_DIM \
    --wd $WD \
    --wds >> "$LOG_FILE" 2>&1

TRAIN_END=$(date +%s)
TRAIN_ELAPSED=$(( TRAIN_END - TRAIN_START ))

echo ""
echo "=== Training Summary ==="
echo "Status: finished at $(date)"
echo "Duration: $(( TRAIN_ELAPSED / 3600 ))h $(( (TRAIN_ELAPSED % 3600) / 60 ))m $(( TRAIN_ELAPSED % 60 ))s"
echo ""

echo "--- Final GPU State ---"
nvidia-smi --query-gpu=index,memory.used,memory.total,temperature.gpu --format=csv,noheader 2>/dev/null
echo ""

echo "--- Final RAM ---"
free -h | grep Mem
echo ""

echo "--- Checkpoints ---"
ls -lh vae/checkpoints/ 2>/dev/null | tail -10
echo ""

echo "--- Last 20 lines of training log ---"
tail -20 "$LOG_FILE" 2>/dev/null
echo ""

echo "Monitor log: $MONITOR_LOG"
